{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 5,
      "text_ar": "فأجابني: «سل امرأة تلد وهي تخبرك.",
      "verse": 51
    },
    {
      "chapter": 5,
      "text_ar": "وقل لها: لماذا ليس الذين ولدتهم الآن مثل الذين سبقوهم، بل هم أصغر قامة؟",
      "verse": 52
    },
    {
      "chapter": 5,
      "text_ar": "وهي أيضاً ستجيبك: إن الذين يولدون في قوة الشباب يختلفون عن الذين يولدون في زمن الشيخوخة عندما يوهن الرحم.",
      "verse": 53
    },
    {
      "chapter": 5,
      "text_ar": "فتأمل أنت أيضاً كيف أنكم أقصر قامة من الذين سبقوكم.",
      "verse": 54
    },
    {
      "chapter": 5,
      "text_ar": "وهكذا فإن الذين يأتون بعدكم أصغر منكم، لأنهم ولدوا من الخليقة التي بدأت تشيخ، وقد تجاوزت قوة الشباب».",
      "verse": 55
    },
    {
      "chapter": 5,
      "text_ar": "فقلت: «يا رب، أتوسل إليك، إن كنت قد وجدت نعمة في عينيك، فأرني عبدك بمن تفتقد خليقتك».",
      "verse": 56
    }
  ]
}
